"""Synthetic Scarlet Book image; contains generated bytes, no recorded music."""
from pathlib import Path


def sacd_image(path):
    sectors = [bytearray(2048) for _ in range(1351)]
    def put(data, offset, value, size=2): data[offset:offset + size] = value.to_bytes(size, "big")
    master = sectors[510]; master[:8] = b"SACDMTOC"; master[8:10] = b"\x01\x14"
    put(master, 16, 1); put(master, 18, 1); put(master, 64, 520, 4); put(master, 84, 6)
    put(master, 120, 2024); master[122:124] = b"\x01\x01"; master[128] = 1
    master[136:140] = b"en\x02\0"
    for index in range(511, 519): sectors[index][:8] = b"SACDText"
    sectors[519][:8] = b"SACD_Man"
    text = sectors[511]; put(text, 16, 64); put(text, 18, 96)
    text[64:64 + 11] = b"Test Album\0"; text[96:96 + 12] = b"Test Artist\0"
    toc = sectors[520]; toc[:8] = b"TWOCHTOC"; toc[8:10] = b"\x01\x14"; put(toc, 10, 6)
    toc[20] = 4; toc[21] = 2; toc[32] = 2; toc[34] = 2; toc[65] = 2; toc[69] = 2
    put(toc, 72, 600, 4); put(toc, 76, 1350, 4); toc[80] = 1; toc[88:92] = b"en\x02\0"
    put(toc, 128, 1)
    text = sectors[521]; text[:8] = b"SACDTTxt"
    for index in range(2):
        at = 64 + index * 96; put(text, 8 + 2 * index, at)
        payload = b"\x02\0\0\0\x01\x20" + f"Track {index + 1}".encode() + b"\0\x02\x20Test Artist\0"
        text[at:at + len(payload)] = payload
    sectors[522][:8] = b"SACD_IGL"
    offsets = sectors[524]; offsets[:8] = b"SACDTRL1"
    times = sectors[525]; times[:8] = b"SACDTRL2"
    for index in range(2):
        put(offsets, 8 + index * 4, 600 + index * 375, 4)
        put(offsets, 8 + 255 * 4 + index * 4, 375, 4)
        times[8 + index * 4 + 1] = index
        times[8 + 255 * 4 + index * 4 + 1] = 1
    for frame in range(150):
        remaining = 9408
        for packet in range(5):
            sector = sectors[600 + frame * 5 + packet]
            first = packet == 0; header = 6 if first else 3
            length = min(2048 - header, remaining); remaining -= length
            sector[0] = 0x24 if first else 0x20
            sector[1] = (0x80 if first else 0) | 0x10 | (length >> 8); sector[2] = length & 255
            if first: sector[3:6] = bytes((0, frame // 75, frame % 75))
            sector[header:header + length] = bytes([0x69 if frame < 75 else 0x96]) * length
    path = Path(path); path.write_bytes(b"".join(sectors)); return path
